<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Service; use Illuminate\Http\Request;
class ServiceController extends Controller { public function guestIndex(){return Service::where('is_available',true)->orderBy('category')->orderBy('name')->get();} public function index(){return Service::latest()->get();} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:150','category'=>'required|in:خدمات الغرف,المغسلة,الكافيه','description'=>'nullable|string','price'=>'required|numeric|min:0','image'=>'nullable|string','is_available'=>'boolean']);return Service::create($d);} public function show(Service $service){return $service;} public function update(Request $r,Service $service){$d=$r->validate(['name'=>'sometimes|string|max:150','category'=>'sometimes|in:خدمات الغرف,المغسلة,الكافيه','description'=>'nullable|string','price'=>'sometimes|numeric|min:0','image'=>'nullable|string','is_available'=>'boolean']);$service->update($d);return $service;} public function destroy(Service $service){$service->delete();return response()->noContent();}}
